"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { TOUR } from "./onboarding-illustration/data";
import { TourDrawing } from "./onboarding-illustration/tour-drawing";

/**
 * A four-step welcome tour for a new clinic: a drawing that reshapes itself
 * on each step, a title and a line, step dots, Back and Next, and Skip.
 * Arrow left and right move between steps.
 */
export function OnboardingIllustration({ className }: { className?: string }) {
  const titleId = useId();
  const reduce = useReducedMotion();
  const [step, setStep] = useState(0);
  const [finished, setFinished] = useState(false);
  const last = TOUR.length - 1;
  const current = TOUR[step]!;

  const goTo = (next: number) => {
    setFinished(false);
    setStep(Math.max(0, Math.min(last, next)));
  };

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === "ArrowRight") goTo(step + 1);
    else if (event.key === "ArrowLeft") goTo(step - 1);
    else return;
    event.preventDefault();
  };

  return (
    <BlockFrame aria-labelledby={titleId} onKeyDown={onKeyDown} className={cn("mx-auto max-w-md", className)}>
      <div className="relative isolate border-b border-border px-5 pt-10 pb-4">
        <span aria-hidden="true" className="absolute inset-0 -z-10 bg-muted/40" />
        <Button variant="ghost" size="sm" className="absolute top-2 right-2" disabled={step === last} onClick={() => goTo(last)}>
          Skip
        </Button>
        <TourDrawing step={step} />
      </div>

      <div className="flex flex-col gap-5 p-5">
        <div aria-live="polite" className="min-h-24">
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={finished ? "done" : step}
              initial={{ opacity: 0, y: reduce ? 0 : 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.18 }}
              className="flex flex-col gap-1.5"
            >
              <p className="text-xs text-muted-foreground">
                Step {step + 1} of {TOUR.length}
              </p>
              <h2 id={titleId} className="text-lg font-semibold text-balance">
                {finished ? "Your tour is done" : current.title}
              </h2>
              <p className="text-sm text-pretty text-muted-foreground">
                {finished ? "Open the schedule from the sidebar whenever you are ready. You can replay this tour from Help." : current.line}
              </p>
            </motion.div>
          </AnimatePresence>
        </div>

        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-1">
            {TOUR.map((item, index) => (
              <Button
                key={item.title}
                variant="ghost"
                size="icon"
                className="size-6"
                aria-label={`Step ${index + 1}: ${item.title}`}
                aria-current={index === step ? "step" : undefined}
                onClick={() => goTo(index)}
              >
                <span
                  aria-hidden="true"
                  className={cn(
                    "h-1.5 rounded-full motion-safe:transition-all",
                    index === step ? "w-4 bg-primary" : "w-1.5 bg-muted-foreground/40",
                  )}
                />
              </Button>
            ))}
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" disabled={step === 0} onClick={() => goTo(step - 1)}>
              Back
            </Button>
            <Button
              size="sm"
              onClick={() => {
                if (step < last) goTo(step + 1);
                else if (finished) goTo(0);
                else setFinished(true);
              }}
            >
              {step < last ? "Next" : finished ? "Replay the tour" : "Get started"}
            </Button>
          </div>
        </div>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** One piece of the drawing in one scene: a rounded rectangle, which becomes a circle when `rx` is half its width. */
export interface Piece {
  x: number;
  y: number;
  w: number;
  h: number;
  rx: number;
}

/** One screen of the tour: its words and where each of the seven pieces sits. */
export interface TourStep {
  title: string;
  line: string;
  pieces: Piece[];
  /** Draws a check mark in the middle, for the closing badge. */
  check?: boolean;
}

const hidden: Piece = { x: 100, y: 60, w: 0, h: 0, rx: 0 };

/** The four screens. Every scene lists seven pieces, so each piece has a place to spring to. */
export const TOUR: TourStep[] = [
  {
    title: "Bring your clinic in",
    line: "Import rooms, services and opening hours from the spreadsheet you already keep.",
    pieces: [
      { x: 60, y: 30, w: 80, h: 58, rx: 6 },
      { x: 60, y: 22, w: 32, h: 14, rx: 4 },
      { x: 54, y: 44, w: 92, h: 46, rx: 6 },
      hidden,
      hidden,
      hidden,
      hidden,
    ],
  },
  {
    title: "Forms ready on day one",
    line: "Intake and consent forms attach to each kind of visit, so patients fill them in before they arrive.",
    pieces: [
      { x: 50, y: 30, w: 44, h: 58, rx: 5 },
      { x: 78, y: 20, w: 44, h: 66, rx: 5 },
      { x: 106, y: 30, w: 44, h: 58, rx: 5 },
      { x: 86, y: 34, w: 28, h: 3, rx: 1.5 },
      { x: 86, y: 44, w: 20, h: 3, rx: 1.5 },
      { x: 86, y: 54, w: 25, h: 3, rx: 1.5 },
      { x: 86, y: 64, w: 16, h: 3, rx: 1.5 },
    ],
  },
  {
    title: "Add the people who treat",
    line: "Each practitioner sets their own hours and the rooms they work from.",
    pieces: [
      { x: 52, y: 38, w: 18, h: 18, rx: 9 },
      { x: 90, y: 26, w: 20, h: 20, rx: 10 },
      { x: 130, y: 38, w: 18, h: 18, rx: 9 },
      { x: 44, y: 60, w: 34, h: 26, rx: 13 },
      { x: 82, y: 50, w: 36, h: 34, rx: 16 },
      { x: 122, y: 60, w: 34, h: 26, rx: 13 },
      hidden,
    ],
  },
  {
    title: "You are ready for bookings",
    line: "Share your booking page and the first patients can pick a time tonight.",
    check: true,
    pieces: [
      { x: 80, y: 66, w: 14, h: 32, rx: 3 },
      { x: 106, y: 66, w: 14, h: 32, rx: 3 },
      { x: 72, y: 18, w: 56, h: 56, rx: 28 },
      { x: 80, y: 26, w: 40, h: 40, rx: 20 },
      hidden,
      hidden,
      hidden,
    ],
  },
];

"use client";

import { motion, type Transition, useReducedMotion } from "motion/react";

import { TOUR } from "./data";

const SPRING: Transition = { type: "spring", stiffness: 260, damping: 24 };
const STROKES = ["stroke-chart-1", "stroke-chart-2", "stroke-chart-3", "stroke-chart-4", "stroke-chart-5"];
const FILLS = ["fill-chart-1/15", "fill-chart-2/15", "fill-chart-3/15", "fill-chart-4/15", "fill-chart-5/15"];

/**
 * The tour's line drawing. The same seven pieces spring from a folder into
 * pages, then a team, then a badge. Reduced motion jumps to each scene.
 */
export function TourDrawing({ step }: { step: number }) {
  const reduce = useReducedMotion();
  const scene = TOUR[step] ?? TOUR[0]!;
  const transition = reduce ? { duration: 0 } : SPRING;

  return (
    <svg viewBox="0 0 200 110" aria-hidden="true" className="h-40 w-full">
      {scene.pieces.map((piece, index) => (
        <motion.rect
          key={index}
          initial={false}
          animate={{ x: piece.x, y: piece.y, width: piece.w, height: piece.h, rx: piece.rx, opacity: piece.w ? 1 : 0 }}
          transition={{ ...transition, delay: reduce ? 0 : index * 0.025 }}
          strokeWidth="2"
          className={`${STROKES[index % 5]} ${FILLS[index % 5]}`}
        />
      ))}
      <motion.path
        d="M88 46l8 8 16-17"
        fill="none"
        strokeWidth="3"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="stroke-chart-2"
        initial={false}
        animate={{ pathLength: scene.check ? 1 : 0, opacity: scene.check ? 1 : 0 }}
        transition={reduce ? { duration: 0 } : { duration: 0.4, delay: scene.check ? 0.25 : 0 }}
      />
    </svg>
  );
}
